from pathlib import Path
import tomllib


def tokens(path="tokens.txt"):
    return [line.strip() for line in Path(path).read_text().splitlines() if line.strip()]


def load(path="replica.toml"):
    settings = tomllib.loads(Path(path).read_text())
    policies = settings["policy"]
    if not isinstance(policies, dict):
        raise SystemExit("policy must define scoped policies")
    for scope in ("catalog_reads", "session_writes"):
        if policies.get(scope) not in tokens():
            raise SystemExit(f"unknown {scope} policy")
    return settings
